// Configuration du workflow « Qualification ».
// C'est le seul nœud à modifier après l'import : renseigne les ID des listes
// Brevo affichés par scripts/setup_brevo.py.
const config = {
  marque: 'Pacewell',
  modele: 'claude-haiku-5-5',
  // Tarifs Claude Haiku 5.5 (USD par million de tokens, prompts < 100k tokens).
  // Source : platform.claude.com/docs/en/about-claude/pricing — à revérifier de temps en temps.
  prixEntreeParMillion: 0.10,
  prixSortieParMillion: 0.50,
  seuilLeadChaud: 70,
  emailAlerte: 'simon59117@gmail.com',
  // Alertes et validations (vers toi) / emails aux inscrits (au nom de la marque).
  expediteur: { email: 'audit@simondelrue.fr', name: 'Pacewell CRM' },
  expediteurMarque: { email: 'audit@simondelrue.fr', name: 'Pacewell' },
  urlSite: 'https://pacewell.simondelrue.fr',
  urlN8n: 'https://n8n.simondelrue.fr',
  // Réactivation : inactif depuis N jours, au plus M propositions par passage.
  joursInactivite: 60,
  maxRelances: 5,
  delaiDoublonJours: 7,
  // Adresses des API (modifiables pour les tests).
  urlBrevo: 'https://api.brevo.com/v3',
  urlClaude: 'https://api.anthropic.com/v1',
  listes: {
    ROUTE_DEBUTANT: 0,
    ROUTE_PERF: 0,
    TRAIL_DECOUVERTE: 0,
    TRAIL_ENDURANCE: 0,
    A_QUALIFIER: 0,
  },
};

// Le webhook range le formulaire dans `body` et les paramètres d'URL dans `query`.
return { formulaire: $json.body ?? {}, query: $json.query ?? {}, config };

// Une ligne par type d'email suivi dans Brevo (étiquette posée à l'envoi).
return [
  { cle: 'bienvenue', tag: 'pacewell-bienvenue', libelle: 'Bienvenue' },
  { cle: 'alerte', tag: 'pacewell-alerte', libelle: 'Alertes lead chaud' },
  { cle: 'relance', tag: 'pacewell-relance', libelle: 'Relances' },
].map((json) => ({ json }));

// ---- Outils communs (ajoutés en tête des nœuds 08 et suivants par construire_workflow.py) ----
// Un nœud Code de n8n ne peut pas importer de fichier : ce bloc est recopié dans chacun.
const e = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const aujourdhui = () => new Date().toISOString().slice(0, 10);
// Retire une salutation en tête de texte (« Salut, ») : le gabarit ajoute déjà « Salut Prénom, ».
const sansSalutation = (t) => String(t ?? '').trim().replace(/^(salut|bonjour|hello|coucou|hey)\b[^\n.!?]{0,30}[,!.]?\s*/i, '').replace(/^\p{Ll}/u, (c) => c.toUpperCase());

const SEGMENTS_LIBELLES = {
  ROUTE_DEBUTANT: 'Route · Débuter', ROUTE_PERF: 'Route · Performance',
  TRAIL_DECOUVERTE: 'Trail · Découverte', TRAIL_ENDURANCE: 'Trail · Endurance et ultra', A_QUALIFIER: 'À qualifier',
};
const NIVEAUX_LIBELLES = { debutant: 'Débutant', intermediaire: 'Intermédiaire', confirme: 'Confirmé' };
const REPONSES_LIBELLES = {
  pratique: { route: 'Route', trail: 'Trail', 'les-deux': 'Route et trail' },
  frequence: { 'moins-1': 'Moins d\'une sortie par semaine', '1-2': '1 à 2 sorties par semaine', '3-4': '3 à 4 sorties par semaine', '5-plus': '5 sorties ou plus par semaine' },
  objectif: { forme: 'Garder la forme', '10km': '10 km', semi: 'Semi-marathon', marathon: 'Marathon', 'trail-court': 'Trail court', ultra: 'Ultra-trail' },
  budget: { 'moins-150': 'Moins de 150 € par an', '150-400': '150 à 400 € par an', '400-plus': 'Plus de 400 € par an' },
};
const lisible = (champ, v) => REPONSES_LIBELLES[champ]?.[v] ?? v ?? '—';

// Ce que l'IA n'a pas le droit d'écrire au nom de la marque : prix, promotions, liens,
// adresses, emoji, promesses de santé. Un texte qui en contient est remplacé par le modèle.
const INTERDITS = [
  [/https?:|www\.|\.(fr|com)\b/i, 'lien'],
  [/@/, 'adresse email'],
  [/€|\d\s*%|\beuros?\b/i, 'prix ou pourcentage'],
  [/promo|réduc|remise|solde|offert|gratuit|cadeau/i, 'promotion'],
  [/guéri|médic|traitement/i, 'promesse de santé'],
  [/\p{Extended_Pictographic}/u, 'emoji'],
];
function problemeTexte(texte, max) {
  if (typeof texte !== 'string' || !texte.trim()) return 'texte vide';
  if (texte.length > max) return `texte trop long (${texte.length} > ${max})`;
  for (const [motif, nom] of INTERDITS) if (motif.test(texte)) return nom;
  return null;
}

// Lit le JSON d'une réponse Claude (réponse HTTP complète de n8n) et calcule son coût.
function lireClaude(reponse, config) {
  const corps = reponse.body || {};
  const usage = corps.usage || {};
  const cout = ((usage.input_tokens || 0) * config.prixEntreeParMillion
    + (usage.output_tokens || 0) * config.prixSortieParMillion) / 1e6;
  const arrondi = Math.round(cout * 1e6) / 1e6;
  if (reponse.statusCode !== 200) return { erreur: `API ${reponse.statusCode || 'injoignable'}`, cout: arrondi };
  const texte = (corps.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
  try {
    return { donnees: JSON.parse(texte.slice(texte.indexOf('{'), texte.lastIndexOf('}') + 1)), cout: arrondi };
  } catch (err) {
    return { erreur: 'JSON illisible', cout: arrondi };
  }
}

// Jeton aléatoire pour les liens de validation (usage unique, stocké dans Brevo).
function jeton() {
  const octets = new Uint8Array(18);
  if (globalThis.crypto?.getRandomValues) globalThis.crypto.getRandomValues(octets);
  else for (let i = 0; i < octets.length; i++) octets[i] = Math.floor(Math.random() * 256);
  return Array.from(octets, (o) => o.toString(16).padStart(2, '0')).join('');
}

// Gabarit HTML des emails de la marque : tableaux et styles en ligne (Gmail, Outlook, mobile).
const COULEURS = { encre: '#10213a', craie: '#e8ebee', piste: '#ff5a1f', gris: '#5b6676', filet: '#dde1e6' };
function gabaritEmail({ marque, etiquette, preheader, corps, pied }) {
  const C = COULEURS;
  return `<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(marque)}</title></head>
<body style="margin:0;padding:0;background:${C.craie}">
<div style="display:none;max-height:0;overflow:hidden">${e(preheader)}</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${C.craie}">
  <tr><td align="center" style="padding:28px 12px">
    <table role="presentation" width="560" cellpadding="0" cellspacing="0" style="width:100%;max-width:560px;background:#ffffff;border-radius:6px;overflow:hidden;font-family:-apple-system,'Segoe UI',Helvetica,Arial,sans-serif;color:${C.encre}">
      <tr><td style="background:${C.encre};padding:18px 28px">
        <span style="font-size:18px;font-weight:800;color:#ffffff;letter-spacing:-0.3px">${e(marque.toLowerCase())}</span>
        ${etiquette ? `<span style="font-size:13px;color:#aab4c3;padding-left:10px">${e(etiquette)}</span>` : ''}
      </td></tr>
${corps}
      <tr><td style="padding:14px 28px;background:#f4f6f8;font-size:12px;line-height:1.5;color:${C.gris}">${pied}</td></tr>
    </table>
  </td></tr>
</table>
</body></html>`;
}
const paragraphe = (texte, style = '') => `<p style="margin:0 0 14px;font-size:16px;line-height:1.55;${style}">${e(texte)}</p>`;
function bouton(libelle, lien, couleur = COULEURS.piste) {
  return `<table role="presentation" cellpadding="0" cellspacing="0"><tr>
          <td style="background:${couleur};border-radius:4px"><a href="${e(lien)}" style="display:inline-block;padding:13px 22px;font-size:15px;font-weight:700;color:#ffffff;text-decoration:none">${e(libelle)}</a></td>
        </tr></table>`;
}
const PIED_DEMO = (marque) => `${e(marque)} est une marque fictive : cet email fait partie d'une démonstration de Simon Delrue, développeur web &amp; IA. Pour supprimer tes données, réponds simplement à cet email.`;
// ---- Fin des outils communs ----

// Étape 4 : calcule les chiffres du tableau de bord (mode « une fois pour tous les éléments »).
// Entrées : les contacts Brevo et les statistiques d'envoi Brevo par étiquette d'email.
// Sortie publique : uniquement des agrégats et le journal des décisions de l'IA,
// jamais d'email ni de prénom.
const { config } = $('Configuration').first().json;
const contacts = ($('Brevo : lister les contacts').first().json.contacts || [])
  .filter((c) => c.attributes && c.attributes.SEGMENT);
const etiquettes = $('Étiquettes à mesurer').all().map((i) => i.json);
const envois = $input.all().map((i) => i.json);
const arrondi = (n, d = 6) => Math.round(n * 10 ** d) / 10 ** d;

const segments = Object.fromEntries(Object.entries(SEGMENTS_LIBELLES).map(([k, libelle]) => [k, { libelle, nombre: 0 }]));
const tranches = Array.from({ length: 10 }, (_, i) => ({ de: i * 10, a: i * 10 + 9, nombre: 0 }));
const relances = { proposees: 0, envoyees: 0, ignorees: 0 };
let sommeScores = 0; let scores = 0; let chauds = 0; let replis = 0; let ia = 0; let cout = 0;

for (const c of contacts) {
  const a = c.attributes;
  if (segments[a.SEGMENT]) segments[a.SEGMENT].nombre++;
  const score = Number(a.SCORE) || 0;
  if (a.SEGMENT !== 'A_QUALIFIER') {
    sommeScores += score; scores++;
    tranches[Math.min(9, Math.floor(score / 10))].nombre++;
    if (score >= config.seuilLeadChaud) chauds++;
  }
  if (a.SOURCE_QUALIF === 'repli') replis++; else ia++;
  cout += Number(a.COUT_IA_USD) || 0;
  if (a.RELANCE_STATUT === 'proposee') relances.proposees++;
  if (a.RELANCE_STATUT === 'envoyee') relances.envoyees++;
  if (a.RELANCE_STATUT === 'ignoree') relances.ignorees++;
}

const emails = {};
etiquettes.forEach((t, i) => {
  const s = envois[i] || {};
  emails[t.cle] = {
    libelle: t.libelle,
    envoyes: s.requests || 0,
    delivres: s.delivered || 0,
    ouvertures: s.uniqueOpens || 0,
    clics: s.uniqueClicks || 0,
    rejets: (s.hardBounces || 0) + (s.softBounces || 0) + (s.blocked || 0),
  };
});

const journal = contacts
  .map((c) => ({ c, date: c.attributes.QUALIFIE_LE || (c.modifiedAt || '').slice(0, 10) }))
  .sort((x, y) => String(y.date).localeCompare(String(x.date)) || String(y.c.modifiedAt).localeCompare(String(x.c.modifiedAt)))
  .slice(0, 15)
  .map(({ c, date }) => ({
    date,
    segment: SEGMENTS_LIBELLES[c.attributes.SEGMENT] ?? c.attributes.SEGMENT,
    niveau: NIVEAUX_LIBELLES[c.attributes.NIVEAU] ?? '',
    score: Number(c.attributes.SCORE) || 0,
    source: c.attributes.SOURCE_QUALIF === 'repli' ? 'Repli' : 'IA',
    raison: String(c.attributes.RAISON_IA || '').slice(0, 250),
  }));

return [{
  json: {
    misAJour: new Date().toISOString(),
    inscrits: contacts.length,
    seuilLeadChaud: config.seuilLeadChaud,
    leadsChauds: chauds,
    scoreMoyen: scores ? Math.round(sommeScores / scores) : 0,
    segments,
    tranchesScore: tranches,
    ia: {
      modele: config.modele,
      qualifications: ia,
      replis,
      tauxRepli: contacts.length ? arrondi(replis / contacts.length, 3) : 0,
      coutTotalUsd: arrondi(cout),
      coutMoyenUsd: contacts.length ? arrondi(cout / contacts.length) : 0,
    },
    relances,
    emails,
    journal,
  },
}];
